namespace ghidra.framework.plugintool.mgr;



using db;
using db;
using ghidra.framework.cmd;
using ghidra.framework.model;
using ghidra.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * A task that executes a command in separate thread, not in the Swing Thread
 */
class BackgroundCommandTask<T> : Task, AbortedTransactionListener where T : DomainObject {

	private BackgroundCommand<T> cmd;
	private ToolTaskManager taskMgr;
	private T obj;

	private bool doneQueueProcessing;

	/**
	 * Constructor
	 * 
	 * @param taskMgr manager for this background task.
	 * @param obj the domain object to be modified by this task.
	 * @param cmd the background command to invoke.
	 */
	public BackgroundCommandTask(ToolTaskManager taskMgr, T obj, BackgroundCommand<T> cmd) : base(cmd.getName(), cmd.canCancel(), cmd.hasProgress(), cmd.isModal())
    {
		this.cmd = cmd;
		this.taskMgr = taskMgr;
		this.obj = obj;
	}

	/**
	 * Returns the Domain Object associated with this Task
	 * @return the object
	 */
	public T getDomainObject() {
		return obj;
	}

	/**
	 * Returns command associated with this task
	 * 
	 * @return background command
	 */
	public BackgroundCommand<T> getCommand() {
		return cmd;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		TaskUtilities.addTrackedTask(this, monitor);
		taskMonitor = monitor;
		int id;
		try {
			id = obj.startTransaction(cmd.getName(), this);
		}
		catch (Throwable t) {
			Msg.error(this, "Transaction error", t);
			monitor.cancel();
			lock (taskMgr) {
				doneQueueProcessing = true;
				taskMgr.clearTasks(obj);
				taskMgr.taskFailed(obj, cmd, monitor);
			}
			TaskUtilities.removeTrackedTask(this);
			return;
		}
		finally {
			lock (taskMgr) {
				// Allow waiting task manager to continue once we have started the transaction
				taskMgr.notifyAll();
			}
		}

		bool success = false;
		bool commit = true;
		try {
			success = cmd.applyTo(obj, monitor);
			if (success) {
				taskMgr.taskCompleted(obj, this, monitor);
			}
		}
		catch (Throwable t) {
			lock (taskMgr) {
				doneQueueProcessing = true;
				taskMgr.clearQueuedCommands(obj);
			}

			if (t is DomainObjectException) {
				t = t.getCause();
			}

			commit = shouldKeepData(t);

			if (isUnrecoverableException(t)) {
				monitor.cancel();
				taskMgr.clearTasks(obj);
			}
			else if (!(t is RollbackException)) {
				string message =
					"An unexpected error occurred while processing the command: " + cmd.getName();
				Msg.showError(this, null, "Command Failure", message, t);
			}
		}
		finally {
			TaskUtilities.removeTrackedTask(this);
			try {
				obj.endTransaction(id, commit);
			}
			catch (DomainObjectException e) {
				Throwable cause = e.getCause();
				if (commit && !(cause is ClosedException)) {
					Msg.error(this, "Transaction error", cause);
					success = false;
				}
			}
		}

		if (!success) {
			taskMgr.taskFailed(obj, cmd, monitor);
		}
	}

	private bool shouldKeepData(Throwable t) {
		// unrecoverable exceptions are really bad; rollback exceptions signal to abort
		bool reallyBad = isUnrecoverableException(t) || t is RollbackException;
		return !reallyBad;
	}

	private bool isUnrecoverableException(Throwable t) {

		//@formatter:off
		return t is ConnectException ||
			   t is NoTransactionException ||
			   t is TerminatedTransactionException ||
			   t is DomainObjectLockedException ||
			   t is ClosedException;
		//@formatter:on
	}

	/* @Override */
	public void transactionAborted(long transactionID) {
		Msg.warn(this, "Forced abort of background task transaction");
		taskMonitor.cancel();
	}

	/**
	 * Mark this task as done queue processing.
	 */
	void setDoneQueueProcessing() {
		doneQueueProcessing = true;
	}

	/**
	 * @return true if task is still pending or actively processing and can
	 *         process new follow-on commands via the task manager.
	 */
	bool isDoneQueueProcessing() {
		return doneQueueProcessing;
	}

}
